	VUZP2 V1.B16, V0.B16, V1.B16
	VMOV V8.B16, V0.B16
	VTBL V6.B16, [V4.B16], V4.B16
	VTBL V7.B16, [V5.B16], V5.B16
	VLD1.P 16(R4), [V8.B16]
	VEOR V4.B16, V8.B16, V8.B16
	AESE V8.B16, V0.B16
	AESMC V0.B16, V0.B16
	AESE V5.B16, V1.B16
	AESMC V1.B16, V1.B16
	AESE V2.B16, V0.B16
	AESMC V0.B16, V0.B16
	AESE V3.B16, V1.B16
	AESMC V1.B16, V1.B16
	VUZP1 V1.B16, V0.B16, V8.B16
	VUZP2 V1.B16, V0.B16, V1.B16
	VMOV V8.B16, V0.B16
	VTBL V6.B16, [V4.B16], V4.B16
	VTBL V7.B16, [V5.B16], V5.B16
	CMP $10, R3
	BEQ v256_blk_arm64_final
	VLD1.P 16(R4), [V8.B16]
	VEOR V4.B16, V8.B16, V8.B16
	AESE V8.B16, V0.B16
	AESMC V0.B16, V0.B16
	AESE V5.B16, V1.B16
	AESMC V1.B16, V1.B16
	AESE V2.B16, V0.B16
	AESMC V0.B16, V0.B16
	AESE V3.B16, V1.B16
	AESMC V1.B16, V1.B16
	VUZP1 V1.B16, V0.B16, V8.B16
	VUZP2 V1.B16, V0.B16, V1.B16
