	VTBL V6.B16, [V4.B16], V4.B16
	VTBL V7.B16, [V5.B16], V5.B16
	MOVD $·vistrutahRoundConstants(SB), R4
	CMP $10, R3
	BEQ v256_dec_blk_rc3
	ADD $80, R4, R5
	VLD1 (R5), [V16.B16]
	VEOR V4.B16, V16.B16, V16.B16
	VEOR V16.B16, V0.B16, V0.B16
	VEOR V5.B16, V1.B16, V1.B16
